    //     xt.r = 0.0;
    //     xt.g = rcpsixth * (twothird - hue);
    //     xt.b = rcpsixth * (hue      - onethird);
    // }

    // if (hue < onethird) {
    //     xt.r = rcpsixth * (onethird - hue);
    //     xt.g = rcpsixth * hue;
    //     xt.b = 0.0;
